 script_content_hash text not null check(script_content_hash~'^[0-9a-f]{64}$'),contract_version text not null,content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),immutable_revision_hash text not null check(immutable_revision_hash~'^[0-9a-f]{64}$'),created_by uuid not null,created_at timestamptz not null default now(),
