 source_plan_revision_id uuid not null,source_plan_revision bigint not null,script_approval_id uuid not null,script_approval_revision bigint not null,source_status text not null check(source_status in('unresolved','linked')),
 source_revision_id uuid,source_revision bigint,workpiece_source_link_revision_id uuid,workpiece_source_link_revision bigint,
