 context_before text not null default '',context_focus text not null,context_after text not null default '',citation_anchor_json jsonb not null default '{}'::jsonb check(jsonb_typeof(citation_anchor_json)='object'),document_locator_json jsonb not null default '{}'::jsonb check(jsonb_typeof(document_locator_json)='object'),media_range_json jsonb not null default '{}'::jsonb check(jsonb_typeof(media_range_json)='object'),
 editorial_reason text not null,desired_material text not null,search_terms jsonb not null default '[]'::jsonb check(jsonb_typeof(search_terms)='array'),placement_hint text not null,duration_target_ms bigint not null check(duration_target_ms between 250 and 120000),creator_direction text,
 content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),immutable_revision_hash text not null check(immutable_revision_hash~'^[0-9a-f]{64}$'),created_by uuid not null,created_at timestamptz not null default now(),
 unique(id,workspace_id,workpiece_id,opportunity_id,revision),unique(workspace_id,workpiece_id,opportunity_id,revision),
 foreign key(source_plan_revision_id,workspace_id,workpiece_id,source_plan_revision) references tongs.reference_visual_plan_revisions(id,workspace_id,workpiece_id,revision),foreign key(previous_revision_id,workspace_id,workpiece_id,opportunity_id,previous_revision) references tongs.reference_visual_opportunity_revisions(id,workspace_id,workpiece_id,opportunity_id,revision),
