alter table tongs.assets drop constraint assets_asset_kind_check,add constraint assets_asset_kind_check check(asset_kind in('thumbnail_image','thumbnail_composite','image_map_json','image_map_candidate_image','broll_candidate_video','broll_candidate_poster','reference_clip_video','reference_clip_poster','reference_visual_image'));
alter table tongs.assets drop constraint assets_kind_shape_check,add constraint assets_kind_shape_check check((asset_kind in('thumbnail_image','thumbnail_composite','broll_candidate_poster','reference_clip_poster','reference_visual_image')and mime_type like'image/%')or(asset_kind='image_map_json'and mime_type='application/json'and prompt is null)or(asset_kind='image_map_candidate_image'and mime_type like'image/%'and prompt is not null)or(asset_kind in('broll_candidate_video','reference_clip_video')and mime_type like'video/%'));
create unique index assets_reference_visual_operation_idx on tongs.assets(workspace_id,workpiece_id,operation_id,asset_kind)where operation_id is not null and asset_kind='reference_visual_image';

create or replace function tongs.reject_reference_visual_immutable_mutation() returns trigger language plpgsql set search_path=pg_catalog,tongs as $$begin raise exception 'reference visual canonical authority is immutable' using errcode='55000';end$$;
do $$declare n text;begin foreach n in array array['reference_visual_plan_revisions','reference_visual_opportunity_revisions','reference_visual_plan_membership','reference_visual_evidence_revisions','reference_visual_recipe_revisions','reference_visual_rights_declaration_revisions','reference_visual_asset_restriction_revisions','reference_visual_candidates','reference_visual_candidate_revisions','reference_visual_sequence_revisions','reference_visual_sequence_membership','reference_visual_selections','reference_visual_operation_receipts'] loop execute format('create trigger %I before update or delete on tongs.%I for each row execute function tongs.reject_reference_visual_immutable_mutation()',n||'_immutable',n);end loop;end$$;
create or replace function tongs.reject_terminal_reference_visual_operation_mutation()returns trigger language plpgsql set search_path=pg_catalog,tongs as $$begin if old.state='candidate_committed'then raise exception 'terminal Reference Visual operation is immutable' using errcode='55000';end if;return new;end$$;
create trigger reference_visual_render_terminal before update or delete on tongs.reference_visual_render_operations for each row execute function tongs.reject_terminal_reference_visual_operation_mutation();
create trigger reference_visual_acquisition_terminal before update or delete on tongs.reference_visual_acquisition_operations for each row execute function tongs.reject_terminal_reference_visual_operation_mutation();

create or replace function tongs.commit_reference_visual_plan(p_workspace_id uuid,p_workpiece_id uuid,p_expected_revision_id uuid,p_expected_revision bigint,p_script_approval_id uuid,p_contract_version text,p_opportunities jsonb,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_plan_sequences%rowtype;approval tongs.script_approval_revisions%rowtype;plan tongs.reference_visual_plan_revisions%rowtype;item jsonb;opp tongs.reference_visual_opportunity_revisions%rowtype;prev tongs.reference_visual_opportunity_revisions%rowtype;oid uuid;n bigint;ordinal integer:=0;h text;ih text;result jsonb;begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if jsonb_typeof(p_opportunities)<>'array' then return jsonb_build_object('disposition','opportunities_array_required');end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 select * into approval from tongs.script_approval_revisions where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id; if not found then return jsonb_build_object('disposition','script_approval_not_found');end if;select * into seq from tongs.reference_visual_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;if coalesce(seq.current_plan_revision,0)<>p_expected_revision or seq.current_plan_revision_id is distinct from p_expected_revision_id then return jsonb_build_object('disposition','plan_revision_conflict','current_revision_id',seq.current_plan_revision_id,'current_revision',coalesce(seq.current_plan_revision,0));end if;n:=p_expected_revision+1;h:=encode(extensions.digest(convert_to(p_opportunities::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',n,'previous_revision_id',seq.current_plan_revision_id,'script_approval_id',approval.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by)values(p_workspace_id,p_workpiece_id,n,seq.current_plan_revision_id,nullif(p_expected_revision,0),approval.id,approval.approval_revision,approval.script_content_hash,p_contract_version,h,ih,p_actor_id)returning * into plan;
