create or replace function tongs.fulfill_reference_visual_opportunity(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,p_expected_opportunity_revision_id uuid,p_expected_opportunity_revision bigint,p_source_revision_id uuid,p_workpiece_source_link_revision_id uuid,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
