ace_id and workpiece_id=p_workpiece_id and source_revision_id=sr.id;if sr.id is null or lr.id is null then return jsonb_build_object('disposition','canonical_source_evidence_required');end if;select * into old_plan from tongs.reference_visual_plan_revisions where id=seq.current_plan_revision_id;h:=encode(extensions.digest(convert_to(jsonb_build_object('previous_plan',old_plan.content_hash,'fulfilled_opportunity',old_opp.id,'source_revision',sr.id,'source_link_revision',lr.id)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',old_plan.revision+1,'previous_revision_id',old_plan.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by)values(p_workspace_id,p_workpiece_id,old_plan.revision+1,old_plan.id,old_plan.revision,old_plan.script_approval_id,old_plan.script_approval_revision,old_plan.script_content_hash,old_plan.contract_version,h,ih,p_actor_id)returning * into new_plan;h:=encode(extensions.digest(convert_to(jsonb_build_object('previous',old_opp.content_hash,'source_revision',sr.id,'source_link_revision',lr.id)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',old_opp.revision+1,'previous_revision_id',old_opp.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_status,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,visual_subtype,context_before,context_focus,context_after,citation_anchor_json,document_locator_json,media_range_json,e