create or replace function tongs.commit_reference_visual_evidence(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,p_evidence_id uuid,p_expected_revision bigint,p_source_revision_id uuid,p_workpiece_source_link_revision_id uuid,p_evidence jsonb,p_confirmation_state text,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_evidence_sequences%rowtype;prev tongs.reference_visual_evidence_revisions%rowtype;sr tongs.source_revisions%rowtype;lr tongs.workpiece_source_link_revisions%rowtype;r tongs.reference_visual_evidence_revisions%rowtype;n bigint;h text;ih text;result jsonb;begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 select * into sr from tongs.source_revisions where id=p_source_revision_id and workspace_id=p_workspace_id;select * into lr from tongs.workpiece_source_link_revisions where id=p_workpiece_source_link_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=sr.id;if sr.id is null or lr.id is null then return jsonb_build_object('disposition','canonical_source_evidence_required');end if;
 select * into seq from tongs.reference_visual_evidence_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and evidence_id=p_evidence_id for update;if coalesce(seq.current_evidence_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','evidence_revision_conflict','current_revision',coalesce(seq.current_evidence_revision,0));end if;if p_expected_revision>0 then select * into prev from tongs.reference_visual_evidence_revisions where id=seq.current_evidence_revision_id;end if;n:=p_expected_revision+1;
 h:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('source_revision_id',sr.id,'source_link_revision_id',lr.id,'evidence',p_evidence,'confirmation_state',p_confirmation_state))::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',n,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');
