 insert into tongs.reference_visual_evidence_sequences values(p_workspace_id,p_workpiece_id,p_evidence_id,r.id,r.revision,now()) on conflict(workspace_id,workpiece_id,evidence_id)do update set current_evidence_revision_id=excluded.current_evidence_revision_id,current_evidence_revision=excluded.current_evidence_revision,updated_at=now();result:=jsonb_build_object('disposition','committed','evidence_revision',to_jsonb(r));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'evidence_commit',p_workspace_id,p_workpiece_id,'committed',r.id,result,p_actor_id,now());return result;end$$;

