 if exists(select 1 from unnest(p_evidence_revision_ids)e(id) left join tongs.reference_visual_evidence_revisions r on r.id=e.id and r.workspace_id=p_workspace_id and r.workpiece_id=p_workpiece_id and r.opportunity_id=p_opportunity_id and r.confirmation_state='creator_confirmed' where r.id is null)then return jsonb_build_object('disposition','confirmed_evidence_required');end if;
