create or replace function tongs.commit_reference_visual_rights_declaration(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,p_declaration_id uuid,p_expected_revision bigint,p_rights_status text,p_declaration jsonb,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_rights_declaration_sequences%rowtype;prev tongs.reference_visual_rights_declaration_revisions%rowtype;r tongs.reference_visual_rights_declaration_revisions%rowtype;n bigint;h text;ih text;result jsonb;begin if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if coalesce((p_declaration->>'creator_acknowledged_responsibility')::boolean,false) is not true then return jsonb_build_object('disposition','creator_rights_acknowledgement_required');end if;if coalesce((p_declaration->>'access_controls_bypassed')::boolean,false) then return jsonb_build_object('disposition','access_control_circumvention_prohibited');end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;select * into seq from tongs.reference_visual_rights_declaration_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id for update;if coalesce(seq.current_declaration_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','rights_revision_conflict','current_revision',coalesce(seq.current_declaration_revision,0));end if;if p_expected_revision>0 then select * into prev from tongs.reference_visual_rights_declaration_revisions where id=seq.current_declaration_revision_id;end if;n:=p_expected_revision+1;h:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('rights_status',p_rights_status,'declaration',p_declaration,'asserted_by',p_actor_id))::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',n,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_rights_declaration_revisions(declaration_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,rights_status,asserted_by,creator_acknowledged_responsibility,rights_holder,license_identifier,license_url,permission_evidence_json,platform_terms_json,fair_use_rationale,territories,expires_at,attribution_required,attribution_text,provenance_json,access_controls_bypassed,content_hash,immutable_revision_hash)values(p_declaration_id,p_workspace_id,p_workpiece_id,p_opportunity_id,n,prev.id,prev.revision,p_rights_status,p_actor_id,true,p_declaration->>'rights_holder',p_declaration->>'license_identifier',p_declaration->>'license_url',coalesce(p_declaration->'permission_evidence','{}'),coalesce(p_declaration->'platform_terms','{}'),p_declaration->>'fair_use_rationale',case when jsonb_typeof(p_declaration->'territories')='array' then array(select jsonb_array_elements_text(p_declaration->'territories')) end,nullif(p_declaration->>'expires_at','')::timestamptz,coalesce((p_declaration->>'attribution_required')::boolean,false),p_declaration->>'attribution_text',coalesce(p_declaration->'provenance','{}'),false,h,ih)returning * into r;insert into tongs.reference_visual_rights_declaration_sequences values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_declaration_id,r.id,r.revision,now())on conflict(workspace_id,workpiece_id,opportunity_id)do update set declaration_id=excluded.declaration_id,current_declaration_revision_id=excluded.current_declaration_revision_id,current_declaration_revision=excluded.current_declaration_revision,updated_at=now();result:=jsonb_build_object('disposition','committed','rights_declaration_revision',to_jsonb(r),'release_ready',p_rights_status<>'rights_unresolved');insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'rights_commit',p_workspace_id,p_workpiece_id,'committed',r.id,result,p_actor_id,now());return result;end$$;

create or replace function tongs.begin_reference_visual_render(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_revision_id uuid,p_recipe_revision_id uuid,p_rights_declaration_revision_id uuid,p_renderer_name text,p_renderer_version text,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_render_operations%rowtype;begin if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_render_operations where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;if not exists(select 1 from tongs.reference_visual_recipe_sequences s join tongs.reference_visual_recipe_revisions r on r.id=s.current_recipe_revision_id where r.id=p_recipe_revision_id and r.workspace_id=p_workspace_id and r.workpiece_id=p_workpiece_id and not exists(select 1 from unnest(r.evidence_revision_ids)e(id) join tongs.reference_visual_evidence_revisions ev on ev.id=e.id where ev.confirmation_state<>'creator_confirmed'))then return jsonb_build_object('disposition','current_confirmed_recipe_required');end if;if not exists(select 1 from tongs.reference_visual_rights_declaration_sequences s where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id and s.current_declaration_revision_id=p_rights_declaration_revision_id)then return jsonb_build_object('disposition','current_rights_declaration_required');end if;insert into tongs.reference_visual_render_operations(operation_id,operation_fingerprint,workspace_id,workpiece_id,opportunity_revision_id,recipe_revision_id,rights_declaration_revision_id,renderer_name,renderer_version,created_by)values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_opportunity_revision_id,p_recipe_revision_id,p_rights_declaration_revision_id,p_renderer_name,p_renderer_version,p_actor_id)returning * into op;return jsonb_build_object('disposition','reserved','operation',to_jsonb(op));end$$;

create or replace function tongs.commit_reference_visual_render(p_operation_id text,p_operation_fingerprint text,p_path text,p_mime_type text,p_byte_size bigint,p_content_hash text,p_storage_bucket text,p_storage_key text,p_width integer,p_height integer,p_render_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_render_operations%rowtype;a tongs.assets%rowtype;c tongs.reference_visual_candidates%rowtype;r tongs.reference_visual_candidate_revisions%rowtype;recipe tongs.reference_visual_recipe_revisions%rowtype;h text;ih text;receipt jsonb;begin if auth.role()<>'service_role' then raise exception 'Reference Visual render commit requires service authority' using errcode='42501';end if;select * into op from tongs.reference_visual_render_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state='candidate_committed' then return op.receipt_json;end if;if p_mime_type not in('image/png','image/svg+xml')or p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$'or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_render_evidence');end if;select * into recipe from tongs.reference_visual_recipe_revisions where id=op.recipe_revision_id;select * into a from tongs.assets where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and operation_id=p_operation_id and asset_kind='reference_visual_image' for update;if found then if a.content_hash<>p_content_hash or a.storage_bucket<>p_storage_bucket or a.storage_key<>p_storage_key or a.bytes<>p_byte_size then return jsonb_build_object('disposition','asset_replay_conflict');end if;else insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,provider_request_id,request_id,created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)values(op.workspace_id,op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,op.renderer_name,p_operation_id,p_operation_id,op.created_by,'reference_visual_image','ready',jsonb_build_object('renderer_name',op.renderer_name,'renderer_version',op.renderer_version,'recipe_revision_id',op.recipe_revision_id),p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now())returning * into a;end if;insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)select op.workspace_id,op.workpiece_id,o.opportunity_id,op.created_by from tongs.reference_visual_opportunity_revisions o where o.id=op.opportunity_revision_id returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset_hash',a.content_hash,'opportunity_revision_id',op.opportunity_revision_id,'recipe_revision_id',recipe.id,'rights_revision_id',op.rights_declaration_revision_id,'renderer',op.renderer_name,'renderer_version',op.renderer_version,'render_evidence',p_render_evidence)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate_id',c.id,'revision',1,'content_hash',h,'operation_id',p_operation_id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,recipe_revision_id,recipe_revision,candidate_kind,asset_id,rights_declaration_revision_id,renderer_name,renderer_version,canonical_render_hash,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)select c.id,op.workspace_id,op.workpiece_id,o.opportunity_id,1,o.id,o.revision,recipe.id,recipe.revision,'rendered_visual',a.id,op.rights_declaration_revision_id,op.renderer_name,op.renderer_version,p_content_hash,p_render_evidence,jsonb_build_object('authority','tongs-render-v1'),h,ih,op.created_by from tongs.reference_visual_opportunity_revisions o where o.id=op.opportunity_revision_id returning * into r;receipt:=jsonb_build_object('disposition','committed','operation_id',p_operation_id,'opportunity_revision_id',op.opportunity_revision_id,'recipe_revision_id',recipe.id,'rights_declaration_revision_id',op.rights_declaration_revision_id,'renderer_name',op.renderer_name,'renderer_version',op.renderer_version,'asset',to_jsonb(a),'candidate_revision',to_jsonb(r));update tongs.reference_visual_render_operations set state='candidate_committed',render_evidence_json=p_render_evidence,output_asset_id=a.id,result_candidate_revision_id=r.id,failed_stage=null,failure_code=null,failure_message=null,receipt_json=receipt,updated_at=now()where operation_id=p_operation_id;return receipt;end$$;

create or replace function tongs.select_reference_visual_candidate(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_id uuid,p_candidate_revision_id uuid,p_expected_plan_revision_id uuid,p_expected_plan_revision bigint,p_expected_selection_revision bigint,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_plan_sequences%rowtype;m tongs.reference_visual_plan_membership%rowtype;c tongs.reference_visual_candidate_revisions%rowtype;prev tongs.reference_visual_selections%rowtype;s tongs.reference_visual_selections%rowtype;asset_id_value uuid;result jsonb;begin if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;select * into seq from tongs.reference_visual_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;if seq.current_plan_revision_id is distinct from p_expected_plan_revision_id or seq.current_plan_revision<>p_expected_plan_revision then return jsonb_build_object('disposition','plan_revision_conflict');end if;select * into m from tongs.reference_visual_plan_membership where plan_revision_id=seq.current_plan_revision_id and opportunity_id=p_opportunity_id;if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;select * into c from tongs.reference_visual_candidate_revisions where id=p_candidate_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and opportunity_revision_id=m.opportunity_revision_id;if not found then return jsonb_build_object('disposition','candidate_not_attached');end if;asset_id_value:=c.asset_id;if asset_id_value is not null and exists(select 1 from tongs.reference_visual_asset_restriction_sequences rs join tongs.reference_visual_asset_restriction_revisions rr on rr.id=rs.current_restriction_revision_id where rs.asset_id=asset_id_value and rr.availability_state in('disputed','disabled'))then return jsonb_build_object('disposition','asset_restricted');end if;select * into prev from tongs.reference_visual_selections where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and plan_revision_id=seq.current_plan_revision_id order by revision desc limit 1;if coalesce(prev.revision,0)<>p_expected_selection_revision then return jsonb_build_object('disposition','selection_revision_conflict','current_revision',coalesce(prev.revision,0));end if;insert into tongs.reference_visual_selections(workspace_id,workpiece_id,opportunity_id,revision,previous_selection_id,previous_revision,plan_revision_id,plan_revision,candidate_revision_id,operation_id,operation_fingerprint,created_by)values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_expected_selection_revision+1,prev.id,prev.revision,seq.current_plan_revision_id,seq.current_plan_revision,c.id,p_operation_id,p_operation_fingerprint,p_actor_id)returning * into s;result:=jsonb_build_object('disposition','committed','selection',to_jsonb(s));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'selection',p_workspace_id,p_workpiece_id,'committed',s.id,result,p_actor_id,now());return result;end$$;

create or replace function tongs.begin_reference_visual_acquisition(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_revision_id uuid,p_rights_declaration_revision_id uuid,p_acquisition_type text,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_acquisition_operations%rowtype;o tongs.reference_visual_opportunity_revisions%rowtype;begin if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_acquisition_operations where operation_id=p_operation_id for update;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;select * into o from tongs.reference_visual_opportunity_revisions where id=p_opportunity_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_status='linked' and visual_subtype in('archival_still','archival_sequence');if not found then return jsonb_build_object('disposition','linked_archival_opportunity_required');end if;if not exists(select 1 from tongs.reference_visual_rights_declaration_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=o.opportunity_id and current_declaration_revision_id=p_rights_declaration_revision_id)then return jsonb_build_object('disposition','current_rights_declaration_required');end if;insert into tongs.reference_visual_acquisition_operations(operation_id,operation_fingerprint,workspace_id,workpiece_id,opportunity_revision_id,rights_declaration_revision_id,acquisition_type,state,created_by)values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_opportunity_revision_id,p_rights_declaration_revision_id,p_acquisition_type,'pending',p_actor_id)returning * into op;return jsonb_build_object('disposition','reserved','operation',to_jsonb(op));end$$;

create or replace function tongs.record_reference_visual_source_acquired(p_operation_id text,p_operation_fingerprint text,p_source_evidence jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_acquisition_operations%rowtype;begin select * into op from tongs.reference_visual_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor')then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state<>'pending' then if op.source_evidence_json is distinct from p_source_evidence then return jsonb_build_object('disposition','source_evidence_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;update tongs.reference_visual_acquisition_operations set state='source_acquired',source_evidence_json=p_source_evidence,failed_stage=null,failure_code=null,failure_message=null,updated_at=now()where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition','source_acquired','operation',to_jsonb(op));end$$;

create or replace function tongs.commit_reference_visual_acquisition(p_operation_id text,p_operation_fingerprint text,p_path text,p_mime_type text,p_byte_size bigint,p_content_hash text,p_storage_bucket text,p_storage_key text,p_width integer,p_height integer,p_provenance jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_acquisition_operations%rowtype;o tongs.reference_visual_opportunity_revisions%rowtype;a tongs.assets%rowtype;c tongs.reference_visual_candidates%rowtype;r tongs.reference_visual_candidate_revisions%rowtype;h text;ih text;receipt jsonb;begin if auth.role()<>'service_role' then raise exception 'Reference Visual acquisition commit requires service authority' using errcode='42501';end if;select * into op from tongs.reference_visual_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state='candidate_committed' then return op.receipt_json;end if;if op.state<>'source_acquired' then return jsonb_build_object('disposition','source_acquisition_required');end if;if p_mime_type not like'image/%'or p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$'or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_image_evidence');end if;select * into o from tongs.reference_visual_opportunity_revisions where id=op.opportunity_revision_id;insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,request_id,created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)values(op.workspace_id,op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,case when op.acquisition_type='upload'then'creator-upload'else'external-fetch'end,p_operation_id,op.created_by,'reference_visual_image','ready',jsonb_build_object('inspection_authority','tongs-service.v1'),p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now())returning * into a;insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(op.workspace_id,op.workpiece_id,o.opportunity_id,op.created_by)returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset_hash',a.content_hash,'opportunity_revision_id',o.id,'rights_revision_id',op.rights_declaration_revision_id,'provenance',p_provenance)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'revision',1,'content_hash',h,'operation',p_operation_id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,candidate_kind,asset_id,rights_declaration_revision_id,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)values(c.id,op.workspace_id,op.workpiece_id,o.opportunity_id,1,o.id,o.revision,'archival_still',a.id,op.rights_declaration_revision_id,'{}',p_provenance,h,ih,op.created_by)returning * into r;receipt:=jsonb_build_object('disposition','committed','operation_id',p_operation_id,'asset',to_jsonb(a),'candidate_revision',to_jsonb(r),'rights_declaration_revision_id',op.rights_declaration_revision_id);update tongs.reference_visual_acquisition_operations set state='candidate_committed',verified_asset_id=a.id,result_candidate_revision_id=r.id,failed_stage=null,failure_code=null,failure_message=null,receipt_json=receipt,updated_at=now()where operation_id=p_operation_id;return receipt;end$$;

create or replace function tongs.commit_reference_visual_sequence(p_workspace_id uuid,p_workpiece_id uuid,p_opportunity_revision_id uuid,p_sequence_id uuid,p_expected_revision bigint,p_rights_declaration_revision_id uuid,p_members jsonb,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_sequence_sequences%rowtype;prev tongs.reference_visual_sequence_revisions%rowtype;s tongs.reference_visual_sequence_revisions%rowtype;o tongs.reference_visual_opportunity_revisions%rowtype;item jsonb;ord integer:=0;c tongs.reference_visual_candidates%rowtype;r tongs.reference_visual_candidate_revisions%rowtype;h text;ih text;result jsonb;begin if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if jsonb_typeof(p_members)<>'array'or jsonb_array_length(p_members)<2 then return jsonb_build_object('disposition','sequence_members_required');end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;select * into o from tongs.reference_visual_opportunity_revisions where id=p_opportunity_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_status='linked' and visual_subtype='archival_sequence';if not found then return jsonb_build_object('disposition','linked_archival_sequence_required');end if;if not exists(select 1 from tongs.reference_visual_rights_declaration_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=o.opportunity_id and current_declaration_revision_id=p_rights_declaration_revision_id)then return jsonb_build_object('disposition','current_rights_declaration_required');end if;select * into seq from tongs.reference_visual_sequence_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=o.opportunity_id for update;if coalesce(seq.current_sequence_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','sequence_revision_conflict','current_revision',coalesce(seq.current_sequence_revision,0));end if;if p_expected_revision>0 then select * into prev from tongs.reference_visual_sequence_revisions where id=seq.current_sequence_revision_id;end if;if exists(select 1 from jsonb_array_elements(p_members)x left join tongs.assets a on a.id=(x->>'asset_id')::uuid and a.workspace_id=p_workspace_id and a.workpiece_id=p_workpiece_id and a.status='ready' and a.mime_type like'image/%' left join tongs.source_revisions sr on sr.id=(x->>'source_revision_id')::uuid and sr.workspace_id=p_workspace_id left join tongs.workpiece_source_link_revisions lr on lr.id=(x->>'workpiece_source_link_revision_id')::uuid and lr.workpiece_id=p_workpiece_id and lr.source_revision_id=sr.id where a.id is null or sr.id is null or lr.id is null)then return jsonb_build_object('disposition','canonical_sequence_member_evidence_required');end if;h:=encode(extensions.digest(convert_to(p_members::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',p_expected_revision+1,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_sequence_revisions(sequence_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,content_hash,immutable_revision_hash,created_by)values(p_sequence_id,p_workspace_id,p_workpiece_id,o.opportunity_id,p_expected_revision+1,prev.id,prev.revision,h,ih,p_actor_id)returning * into s;for item in select value from jsonb_array_elements(p_members)loop insert into tongs.reference_visual_sequence_membership values(s.id,p_workspace_id,p_workpiece_id,ord,(item->>'asset_id')::uuid,(item->>'source_revision_id')::uuid,(item->>'workpiece_source_link_revision_id')::uuid,nullif(item->>'duration_ms','')::bigint,coalesce(item->'transition_hints','{}'));ord:=ord+1;end loop;insert into tongs.reference_visual_sequence_sequences values(p_workspace_id,p_workpiece_id,o.opportunity_id,p_sequence_id,s.id,s.revision,now())on conflict(workspace_id,workpiece_id,opportunity_id)do update set sequence_id=excluded.sequence_id,current_sequence_revision_id=excluded.current_sequence_revision_id,current_sequence_revision=excluded.current_sequence_revision,updated_at=now();insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(p_workspace_id,p_workpiece_id,o.opportunity_id,p_actor_id)returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('sequence_revision_id',s.id,'rights_revision_id',p_rights_declaration_revision_id)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'revision',1,'content_hash',h)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,candidate_kind,sequence_revision_id,rights_declaration_revision_id,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)values(c.id,p_workspace_id,p_workpiece_id,o.opportunity_id,1,o.id,o.revision,'archival_sequence',s.id,p_rights_declaration_revision_id,'{}',jsonb_build_object('authority','tongs-sequence-v1'),h,ih,p_actor_id)returning * into r;result:=jsonb_build_object('disposition','committed','sequence_revision',to_jsonb(s),'candidate_revision',to_jsonb(r));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'sequence_commit',p_workspace_id,p_workpiece_id,'committed',s.id,result,p_actor_id,now());return result;end$$;

create or replace function tongs.fail_reference_visual_operation(p_operation_kind text,p_operation_id text,p_operation_fingerprint text,p_failed_stage text,p_failure_code text,p_failure_message text)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare result jsonb;begin if p_operation_kind='render'then update tongs.reference_visual_render_operations set failed_stage=p_failed_stage,failure_code=p_failure_code,failure_message=p_failure_message,updated_at=now()where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint and state<>'candidate_committed' and tongs.has_workspace_role(workspace_id,'editor')returning jsonb_build_object('disposition','failure_recorded','operation',to_jsonb(reference_visual_render_operations))into result;elsif p_operation_kind='acquisition'then update tongs.reference_visual_acquisition_operations set failed_stage=p_failed_stage,failure_code=p_failure_code,failure_message=p_failure_message,updated_at=now()where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint and state<>'candidate_committed' and tongs.has_workspace_role(workspace_id,'editor')returning jsonb_build_object('disposition','failure_recorded','operation',to_jsonb(reference_visual_acquisition_operations))into result;else return jsonb_build_object('disposition','invalid_operation_kind');end if;return coalesce(result,jsonb_build_object('disposition','operation_not_found_or_terminal'));end$$;

create or replace function tongs.commit_reference_visual_asset_restriction(p_workspace_id uuid,p_workpiece_id uuid,p_asset_id uuid,p_expected_revision bigint,p_availability_state text,p_reason_code text,p_notice_reference text,p_decision_note text,p_operation_id text,p_operation_fingerprint text,p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,tongs as $$declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_asset_restriction_sequences%rowtype;prev tongs.reference_visual_asset_restriction_revisions%rowtype;r tongs.reference_visual_asset_restriction_revisions%rowtype;rid uuid;n bigint;h text;ih text;result jsonb;begin if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if not exists(select 1 from tongs.assets where id=p_asset_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id)then return jsonb_build_object('disposition','asset_not_found');end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;select * into seq from tongs.reference_visual_asset_restriction_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and asset_id=p_asset_id for update;if coalesce(seq.current_restriction_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','restriction_revision_conflict');end if;if p_expected_revision>0 then select * into prev from tongs.reference_visual_asset_restriction_revisions where id=seq.current_restriction_revision_id;end if;rid:=coalesce(seq.restriction_id,gen_random_uuid());n:=p_expected_revision+1;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset_id',p_asset_id,'availability_state',p_availability_state,'reason_code',p_reason_code,'notice_reference',p_notice_reference,'decision_note',p_decision_note)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',n,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_asset_restriction_revisions(restriction_id,workspace_id,workpiece_id,asset_id,revision,previous_revision_id,previous_revision,availability_state,reason_code,notice_reference,decision_note,acted_by,content_hash,immutable_revision_hash)values(rid,p_workspace_id,p_workpiece_id,p_asset_id,n,prev.id,prev.revision,p_availability_state,p_reason_code,p_notice_reference,p_decision_note,p_actor_id,h,ih)returning * into r;insert into tongs.reference_visual_asset_restriction_sequences values(p_workspace_id,p_workpiece_id,p_asset_id,rid,r.id,r.revision,now())on conflict(workspace_id,workpiece_id,asset_id)do update set current_restriction_revision_id=excluded.current_restriction_revision_id,current_restriction_revision=excluded.current_restriction_revision,updated_at=now();result:=jsonb_build_object('disposition','committed','restriction_revision',to_jsonb(r));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'asset_restriction',p_workspace_id,p_workpiece_id,'committed',r.id,result,p_actor_id,now());return result;end$$;

create or replace function tongs.reference_visual_candidate_assets_available(p_candidate_revision_id uuid)returns boolean language sql stable security definer set search_path=pg_catalog,tongs as $$
select not exists(
 select 1 from tongs.reference_visual_candidate_revisions c
 join lateral(select c.asset_id as asset_id where c.asset_id is not null union all select sm.asset_id from tongs.reference_visual_sequence_membership sm where sm.sequence_revision_id=c.sequence_revision_id)member on true
 join tongs.reference_visual_asset_restriction_sequences rs on rs.asset_id=member.asset_id
 join tongs.reference_visual_asset_restriction_revisions rr on rr.id=rs.current_restriction_revision_id
 where c.id=p_candidate_revision_id and rr.availability_state in('disputed','disabled')
)$$;

create or replace function tongs.reject_restricted_reference_visual_selection()returns trigger language plpgsql set search_path=pg_catalog,tongs as $$begin if not tongs.reference_visual_candidate_assets_available(new.candidate_revision_id)then raise exception 'asset_restricted' using errcode='23514';end if;return new;end$$;
create trigger reference_visual_selection_assets_available before insert on tongs.reference_visual_selections for each row execute function tongs.reject_restricted_reference_visual_selection();

create or replace function tongs.read_current_reference_visual_plan(p_workspace_id uuid,p_workpiece_id uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,tongs as $$
select case when not tongs.has_workspace_role(p_workspace_id,'viewer')then null else(
 select jsonb_build_object('sequence',to_jsonb(s),'plan_revision',to_jsonb(p),'opportunities',coalesce((
  select jsonb_agg(jsonb_build_object(
   'membership',to_jsonb(m),'opportunity_revision',to_jsonb(o),'source_revision',to_jsonb(sr),'source_link_revision',to_jsonb(lr),
   'evidence',coalesce((select jsonb_agg(to_jsonb(e)order by e.created_at)from tongs.reference_visual_evidence_sequences es join tongs.reference_visual_evidence_revisions e on e.id=es.current_evidence_revision_id where es.workspace_id=m.workspace_id and es.workpiece_id=m.workpiece_id and e.opportunity_id=m.opportunity_id),'[]'::jsonb),
   'recipe',to_jsonb(rr),'rights_declaration',to_jsonb(rd),
   'candidates',coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('asset',to_jsonb(a),'asset_restriction',to_jsonb(ar),'release_ready',rd.rights_status<>'rights_unresolved'and tongs.reference_visual_candidate_assets_available(c.id))order by c.created_at)from tongs.reference_visual_candidate_revisions c left join tongs.assets a on a.id=c.asset_id left join tongs.reference_visual_asset_restriction_sequences ars on ars.asset_id=c.asset_id left join tongs.reference_visual_asset_restriction_revisions ar on ar.id=ars.current_restriction_revision_id where c.workspace_id=m.workspace_id and c.workpiece_id=m.workpiece_id and c.opportunity_id=m.opportunity_id),'[]'::jsonb),
   'selection',to_jsonb(sel),'release_ready',sel.id is not null and rd.rights_status<>'rights_unresolved'and tongs.reference_visual_candidate_assets_available(sel.candidate_revision_id)
  )order by m.ordinal)
  from tongs.reference_visual_plan_membership m join tongs.reference_visual_opportunity_revisions o on o.id=m.opportunity_revision_id
  left join tongs.source_revisions sr on sr.id=o.source_revision_id left join tongs.workpiece_source_link_revisions lr on lr.id=o.workpiece_source_link_revision_id
  left join tongs.reference_visual_recipe_sequences rs on rs.workspace_id=m.workspace_id and rs.workpiece_id=m.workpiece_id and rs.opportunity_id=m.opportunity_id left join tongs.reference_visual_recipe_revisions rr on rr.id=rs.current_recipe_revision_id
  left join tongs.reference_visual_rights_declaration_sequences rds on rds.workspace_id=m.workspace_id and rds.workpiece_id=m.workpiece_id and rds.opportunity_id=m.opportunity_id left join tongs.reference_visual_rights_declaration_revisions rd on rd.id=rds.current_declaration_revision_id
  left join lateral(select x.* from tongs.reference_visual_selections x where x.workspace_id=m.workspace_id and x.workpiece_id=m.workpiece_id and x.opportunity_id=m.opportunity_id and x.plan_revision_id=m.plan_revision_id order by x.revision desc limit 1)sel on true
  where m.plan_revision_id=s.current_plan_revision_id
 ),'[]'::jsonb))from tongs.reference_visual_plan_sequences s join tongs.reference_visual_plan_revisions p on p.id=s.current_plan_revision_id where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id
)end$$;

do $$declare n text;begin foreach n in array array['reference_visual_plan_revisions','reference_visual_plan_sequences','reference_visual_opportunity_revisions','reference_visual_plan_membership','reference_visual_evidence_revisions','reference_visual_evidence_sequences','reference_visual_recipe_revisions','reference_visual_recipe_sequences','reference_visual_rights_declaration_revisions','reference_visual_rights_declaration_sequences','reference_visual_asset_restriction_revisions','reference_visual_asset_restriction_sequences','reference_visual_candidates','reference_visual_candidate_revisions','reference_visual_sequence_revisions','reference_visual_sequence_sequences','reference_visual_sequence_membership','reference_visual_selections','reference_visual_render_operations','reference_visual_acquisition_operations','reference_visual_operation_receipts'] loop execute format('alter table tongs.%I enable row level security',n);execute format('create policy %I on tongs.%I for select to authenticated using(tongs.has_workspace_role(workspace_id,''viewer''))',n||'_viewer',n);execute format('revoke all on tongs.%I from public,anon,authenticated',n);execute format('grant select on tongs.%I to authenticated',n);end loop;end$$;
revoke all on function tongs.commit_reference_visual_plan(uuid,uuid,uuid,bigint,uuid,text,jsonb,text,text,uuid),tongs.fulfill_reference_visual_opportunity(uuid,uuid,uuid,uuid,bigint,uuid,uuid,text,text,uuid),tongs.commit_reference_visual_evidence(uuid,uuid,uuid,uuid,bigint,uuid,uuid,jsonb,text,text,text,uuid),tongs.commit_reference_visual_recipe(uuid,uuid,uuid,uuid,bigint,text,text,text,text,jsonb,uuid[],text,text,text,jsonb,jsonb,jsonb,text,text,text,uuid),tongs.commit_reference_visual_rights_declaration(uuid,uuid,uuid,uuid,bigint,text,jsonb,text,text,uuid),tongs.begin_reference_visual_render(uuid,uuid,uuid,uuid,uuid,text,text,text,text,uuid),tongs.begin_reference_visual_acquisition(uuid,uuid,uuid,uuid,text,text,text,uuid),tongs.record_reference_visual_source_acquired(text,text,jsonb),tongs.commit_reference_visual_sequence(uuid,uuid,uuid,uuid,bigint,uuid,jsonb,text,text,uuid),tongs.select_reference_visual_candidate(uuid,uuid,uuid,uuid,uuid,bigint,bigint,text,text,uuid),tongs.fail_reference_visual_operation(text,text,text,text,text,text),tongs.commit_reference_visual_asset_restriction(uuid,uuid,uuid,bigint,text,text,text,text,text,text,uuid) from public,anon,authenticated;
grant execute on function tongs.commit_reference_visual_plan(uuid,uuid,uuid,bigint,uuid,text,jsonb,text,text,uuid),tongs.fulfill_reference_visual_opportunity(uuid,uuid,uuid,uuid,bigint,uuid,uuid,text,text,uuid),tongs.commit_reference_visual_evidence(uuid,uuid,uuid,uuid,bigint,uuid,uuid,jsonb,text,text,text,uuid),tongs.commit_reference_visual_recipe(uuid,uuid,uuid,uuid,bigint,text,text,text,text,jsonb,uuid[],text,text,text,jsonb,jsonb,jsonb,text,text,text,uuid),tongs.commit_reference_visual_rights_declaration(uuid,uuid,uuid,uuid,bigint,text,jsonb,text,text,uuid),tongs.begin_reference_visual_render(uuid,uuid,uuid,uuid,uuid,text,text,text,text,uuid),tongs.begin_reference_visual_acquisition(uuid,uuid,uuid,uuid,text,text,text,uuid),tongs.record_reference_visual_source_acquired(text,text,jsonb),tongs.commit_reference_visual_sequence(uuid,uuid,uuid,uuid,bigint,uuid,jsonb,text,text,uuid),tongs.select_reference_visual_candidate(uuid,uuid,uuid,uuid,uuid,bigint,bigint,text,text,uuid),tongs.fail_reference_visual_operation(text,text,text,text,text,text),tongs.commit_reference_visual_asset_restriction(uuid,uuid,uuid,bigint,text,text,text,text,text,text,uuid),tongs.read_current_reference_visual_plan(uuid,uuid) to authenticated,service_role;
revoke all on function tongs.commit_reference_visual_render(text,text,text,text,bigint,text,text,text,integer,integer,jsonb),tongs.commit_reference_visual_acquisition(text,text,text,text,bigint,text,text,text,integer,integer,jsonb)from public,anon,authenticated;
grant execute on function tongs.commit_reference_visual_render(text,text,text,text,bigint,text,text,text,integer,integer,jsonb),tongs.commit_reference_visual_acquisition(text,text,text,text,bigint,text,text,text,integer,integer,jsonb)to service_role;
revoke all on function tongs.reference_visual_candidate_assets_available(uuid),tongs.reject_restricted_reference_visual_selection()from public,anon;
grant execute on function tongs.reference_visual_candidate_assets_available(uuid)to authenticated,service_role;
comment on table tongs.reference_visual_evidence_revisions is 'Immutable Source-relative facts and excerpts; AI extraction is not renderable until creator-confirmed.';
comment on table tongs.reference_visual_recipe_revisions is 'Immutable creator-reviewable render recipes consuming exact confirmed evidence revisions.';
comment on table tongs.reference_visual_rights_declaration_revisions is 'Creator assertions preserved as evidence; fair_use_asserted_by_creator is never a Forge legal determination.';
comment on table tongs.reference_visual_asset_restriction_revisions is 'Immutable availability decisions allow disputed media to be disabled without deleting canonical history.';
